OB64
          if [ "$(sha256sum "$ODIR/office-server.py" | cut -d' ' -f1)" != "7a9c3f0342026294bfe39f3226fc92d04b77be78a39822bb9286a246e30f11f7" ]; then echo "   File del servizio Office non integro: saltato."
          else
            $SUDO chmod 755 "$ODIR"; $SUDO chmod 644 "$ODIR/office-server.py"
            if ! $SUDO test -s "$KDIR/office.key"; then
              $SUDO sh -c 'umask 077; set -C; head -c 24 /dev/urandom | od -An -tx1 | tr -d " \n" > "$1"' _ "$KDIR/office.key" || true
              $SUDO chown 1000:1000 "$KDIR/office.key" 2>/dev/null || true; $SUDO chmod 600 "$KDIR/office.key"
            fi
            OIMG="giot-office:2"   # :2 = Python completo (la :1 usava python3-minimal, senza il modulo hmac: non partiva)
            if ! $SUDO docker image inspect "$OIMG" >/dev/null 2>&1; then
              echo "   Preparo il servizio Office (la prima volta scarica LibreOffice: 5-10 minuti, una volta sola)"
              OBD=$(mktemp -d)
              cat > "$OBD/Dockerfile" <<'DF'
FROM ubuntu:24.04
ENV DEBIAN_FRONTEND=noninteractive
RUN apt-get update && apt-get install -y --no-install-recommends libreoffice-writer-nogui libreoffice-calc-nogui python3 fonts-liberation fonts-dejavu-core fonts-crosextra-carlito fonts-crosextra-caladea ca-certificates procps && rm -rf /var/lib/apt/lists/*
DF
              if ! $SUDO timeout 1500 docker build -t "$OIMG" "$OBD" > /tmp/giot-office-build.log 2>&1; then
                echo "   Costruzione del servizio Office non riuscita. Ultime righe (registro completo in /tmp/giot-office-build.log):"
                tail -n 8 /tmp/giot-office-build.log | sed 's/^/      /'
              fi
              rm -rf "$OBD"
              $SUDO docker image inspect "$OIMG" >/dev/null 2>&1 && { $SUDO docker rm -f giot-office >/dev/null 2>&1 || true; $SUDO docker image rm giot-office:1 >/dev/null 2>&1 || true; }
            fi
            if $SUDO docker image inspect "$OIMG" >/dev/null 2>&1; then
              $SUDO docker rm -f giot-office >/dev/null 2>&1 || true
              if $SUDO docker run -d --name giot-office --restart unless-stopped --network host --read-only --tmpfs /tmp:size=384m \
                   --log-opt max-size=10m --log-opt max-file=3 --cap-drop ALL --security-opt no-new-privileges --memory "$([ "${MEMMB:-0}" -lt 1800 ] && echo 640m || echo 1g)" --pids-limit 200 --oom-score-adj 500 --user 1000:1000 \
                   -e OFFICE_PORT=3003 -e OFFICE_BIND=127.0.0.1 -e OFFICE_KEY="$($SUDO cat "$KDIR/office.key")" \
                   -v "$ODIR":/app:ro "$OIMG" python3 /app/office-server.py >/dev/null 2>&1; then
                sleep "${OFFICE_SETTLE:-12}"
                OST=$($SUDO docker inspect -f '{{.State.Running}} {{.State.Restarting}} {{.RestartCount}}' giot-office 2>/dev/null || echo "false false 0")
                if [ "$OST" = "true false 0" ]; then
                  OFFICE_ENV="-e OFFICE_URL=http://127.0.0.1:3003 -e OFFICE_KEY_FILE=/key/office.key"
                  echo "   Servizio Office attivo (solo su questa macchina, 127.0.0.1:3003)."
                else
                  echo "   Servizio Office si riavvia di continuo: lo spengo per non consumare memoria. Ultime righe del suo registro:"
                  $SUDO docker logs --tail 8 giot-office 2>&1 | sed 's/^/      /'
                  $SUDO docker rm -f giot-office >/dev/null 2>&1 || true
                  echo "   I .doc useranno la copia semplificata."
                fi
              else echo "   Servizio Office non avviato: i .doc useranno la copia semplificata."; fi
            else echo "   Servizio Office non disponibile: i .doc useranno la copia semplificata."; fi
          fi
        fi
        # --- banco di lavoro di Code (giot-sandbox): contenitore SEPARATO, senza chiavi né dati della chat,
        #     su una rete che non raggiunge i servizi del server (FreeLLMAPI, archivio, Office) né i metadati del cloud ---
        SB_ENV=""; SBMODE="${SANDBOX_MODE:-auto}"
        SDIR="${SDIR:-/opt/giot-sandbox}"; WSDIR="${WSDIR:-/opt/giot-workspaces}"; APPSDIR="${APPSDIR:-/opt/giot-apps}"; UNITDIR="${UNITDIR:-/etc/systemd/system}"
        if [ "$SBMODE" = skip ]; then echo "   Code: banco di lavoro saltato su richiesta."
        elif [ "${MEMMB:-0}" -lt 700 ] && [ "$SBMODE" != force ]; then echo "   Code: saltato (servono almeno ~700 MB di RAM, qui ce ne sono ${MEMMB:-?} MB)."
        else
          # macchine piccole (es. Oracle E2.1.Micro, 1 GB): versione leggera, un comando alla volta e memoria contenuta
          SWAPMB=$(awk '/SwapTotal/ {print int($2/1024)}' /proc/meminfo 2>/dev/null || echo 0); SWAPMB="${SWAPMB_OVERRIDE:-$SWAPMB}"
          if [ "${MEMMB:-0}" -lt 1800 ]; then SBMEM=384m; SBPIDS=128; SBXTRA="-e SB_LIGHT=1 -e SB_MAX_GLOBAL=1 -e SB_NODE_OPTIONS=--max-old-space-size=256"; SBDESC="versione leggera: ${MEMMB} MB di RAM sul server"
          else SBMEM=1g; SBPIDS=256; SBXTRA=""; SBDESC="1 GB riservato"; fi
          $SUDO mkdir -p "$SDIR" "$WSDIR" "$APPSDIR"
          base64 -d <<'SB64' | gunzip | $SUDO tee "$SDIR/sandbox-server.mjs" >/dev/null
